pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= address(c).balance);
        uint256 balanceBefore = address(c).balance;
        try c.go{value: amount}() {
            assertTrue(address(c).balance == 0);
        } catch {
            // if revert, balance unchanged; but we want the rule for non-revert
            assertTrue(address(c).balance == balanceBefore);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= address(c).balance);
        vm.deal(address(0xCAFE), amount);
        address owner = c.owner();
        uint256 contractBalanceBefore = address(c).balance;
        uint256 ownerBalanceBefore = owner.balance;

        vm.prank(owner);
        (bool success,) = address(c).call{value: amount}(abi.encodeWithSignature("go()"));
        require(success, "go() reverted");

        uint256 sumAfter = address(c).balance + owner.balance;
        uint256 sumBefore = contractBalanceBefore + ownerBalanceBefore + amount;
        assertTrue(sumAfter == sumBefore, "Sum invariant broken");
    }
}

