pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount < address(c).balance);
        uint256 beforeBalance = address(c).balance;
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSignature("go()"));
        assertTrue(success);
        assertTrue(address(c).balance >= beforeBalance);
    }
}
